import Foundation

/// Loads the vocabulary bundle (`vocab-bundle.json`, generated by `Tools/build_bundle.py`).
enum ContentStore {
    enum LoadError: Error, LocalizedError {
        case missingResource

        var errorDescription: String? { "vocab-bundle.json is missing from the app bundle." }
    }

    static func load(from data: Data) throws -> ContentIndex {
        ContentIndex(bundle: try JSONDecoder().decode(VocabBundle.self, from: data))
    }

    static func loadBundled(in bundle: Bundle = .main) throws -> ContentIndex {
        guard let url = bundle.url(forResource: "vocab-bundle", withExtension: "json") else {
            throw LoadError.missingResource
        }
        return try load(from: Data(contentsOf: url))
    }
}
